<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="list-head"><div><p>Content manager</p><h1><?= esc($meta['label']) ?></h1></div><?php if ($entity !== 'inquiries'): ?><a class="primary" href="<?= site_url('admin/' . $entity . '/new') ?>">Add <?= rtrim(strtolower($meta['label']), 's') ?></a><?php endif ?></section><div class="table-wrap"><table><thead><tr><th>Title / name</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= esc($row['title'] ?? $row['name'] ?? '') ?></strong><small><?= esc($row['slug'] ?? $row['email'] ?? '') ?></small></td><td><span class="badge <?= esc($row['status'] ?? '') ?>"><?= esc($row['status'] ?? '') ?></span></td><td><?= esc($row['updated_at'] ?? '') ?></td><td class="actions"><a href="<?= site_url('admin/' . $entity . '/' . $row['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('admin/' . $entity . '/' . $row['id'] . '/delete') ?>" onsubmit="return confirm('Delete this item?')"><?= csrf_field() ?><button>Delete</button></form></td></tr><?php endforeach ?><?php if (! $rows): ?><tr><td colspan="4">Nothing here yet.</td></tr><?php endif ?></tbody></table></div><?= $this->endSection() ?>
